"""Design tokens and accessible offline CSS."""


def theme_css():
    return """
:root{--bg:#f6f8fb;--surface:#fff;--surface-muted:#f1f4f8;--text:#172033;--text-muted:#667085;--primary:#315efb;--positive:#16845b;--warning:#b7791f;--negative:#c0392b;--blocked:#7f1d1d;--border:#e4e7ec;--radius:14px;--shadow:0 8px 24px rgba(16,24,40,.08)}
@media(prefers-color-scheme:dark){:root{--bg:#101827;--surface:#172033;--surface-muted:#202b3d;--text:#f3f6fb;--text-muted:#aab5c5;--border:#344155}}
body{background:var(--bg);color:var(--text)}.dashboard-topbar{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;margin-bottom:14px}.dashboard-topbar h1{margin-bottom:4px}.dashboard-statuses{display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end}.state-badge{display:inline-flex;align-items:center;gap:5px;border:1px solid currentColor;border-radius:999px;padding:4px 9px;font-size:11px;font-weight:700;letter-spacing:.02em}.state-badge[data-state=live_certified],.state-badge[data-state=fresh],.state-badge[data-state=completed]{color:var(--positive);background:#e8f7ef}.state-badge[data-state=degraded],.state-badge[data-state=stale],.state-badge[data-state=uncalibrated]{color:var(--warning);background:#fff8e5}.state-badge[data-state=blocked],.state-badge[data-state=ood_detected],.state-badge[data-state=failed]{color:var(--blocked);background:#fff0f0}.state-badge[data-state=not_available]{color:var(--text-muted);background:var(--surface-muted)}.dashboard-nav{position:sticky;top:0;z-index:2;display:flex;gap:5px;overflow:auto;padding:7px 0;margin:0 0 16px;background:color-mix(in srgb,var(--bg) 90%,transparent);backdrop-filter:blur(8px)}.dashboard-nav a{color:var(--text-muted);text-decoration:none;border:1px solid var(--border);border-radius:9px;padding:6px 11px;white-space:nowrap;background:var(--surface)}.dashboard-nav a:focus-visible{outline:3px solid var(--primary);outline-offset:2px}.dashboard-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-bottom:16px}.dashboard-kpi{background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);box-shadow:var(--shadow);padding:13px;min-height:76px}.dashboard-kpi span{display:block;color:var(--text-muted);font-size:11px}.dashboard-kpi strong{display:block;font-size:18px;margin-top:3px;overflow-wrap:anywhere}.source-matrix{margin:16px 0}.source-matrix h2{margin-bottom:8px}.source-matrix table{min-width:680px}.source-matrix .state-badge{font-size:10px;padding:2px 7px}.chart [data-tooltip]{cursor:help}.chart [data-tooltip]:hover{filter:brightness(.85)}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}@media(max-width:760px){.dashboard-topbar{display:block}.dashboard-statuses{justify-content:flex-start;margin-top:8px}.dashboard-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}
body{background:var(--bg);color:var(--text)}.dashboard-topbar{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;margin-bottom:14px}.dashboard-topbar h1{margin-bottom:4px}.dashboard-statuses{display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end}.state-badge{display:inline-flex;align-items:center;gap:5px;border:1px solid currentColor;border-radius:999px;padding:4px 9px;font-size:11px;font-weight:700;letter-spacing:.02em}.state-badge[data-state=live_certified],.state-badge[data-state=fresh],.state-badge[data-state=completed]{color:var(--positive);background:#e8f7ef}.state-badge[data-state=degraded],.state-badge[data-state=stale],.state-badge[data-state=uncalibrated]{color:var(--warning);background:#fff8e5}.state-badge[data-state=blocked],.state-badge[data-state=ood_detected],.state-badge[data-state=failed]{color:var(--blocked);background:#fff0f0}.state-badge[data-state=not_available]{color:var(--text-muted);background:var(--surface-muted)}.dashboard-nav{position:sticky;top:0;z-index:2;display:flex;gap:5px;overflow:auto;padding:7px 0;margin:0 0 16px;background:color-mix(in srgb,var(--bg) 90%,transparent);backdrop-filter:blur(8px)}.dashboard-nav button{color:var(--text-muted);border:1px solid var(--border);border-radius:9px;padding:6px 11px;white-space:nowrap;background:var(--surface);cursor:pointer}.dashboard-nav button[aria-selected=true]{color:var(--primary);border-color:var(--primary)}.dashboard-nav button:focus-visible{outline:3px solid var(--primary);outline-offset:2px}.dashboard-controls{display:flex;align-items:end;gap:10px;flex-wrap:wrap;background:var(--surface-muted);border:1px solid var(--border);border-radius:var(--radius);padding:10px;margin-bottom:16px}.dashboard-controls label{display:flex;flex-direction:column;gap:3px;font-size:11px;color:var(--text-muted)}.dashboard-controls select,.dashboard-controls button{min-height:31px;border:1px solid var(--border);border-radius:8px;background:var(--surface);color:var(--text);padding:4px 8px}.dashboard-controls button{cursor:pointer}.dashboard-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-bottom:16px}.dashboard-kpi{background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);box-shadow:var(--shadow);padding:13px;min-height:76px}.dashboard-kpi span{display:block;color:var(--text-muted);font-size:11px}.dashboard-kpi strong{display:block;font-size:18px;margin-top:3px;overflow-wrap:anywhere}.source-matrix{margin:16px 0}.source-matrix h2{margin-bottom:8px}.source-matrix table{min-width:680px}.source-matrix .state-badge{font-size:10px;padding:2px 7px}.explanation-card{background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);box-shadow:var(--shadow);padding:14px}.explanation-card img{max-width:100%;height:auto}.formula-card{background:var(--surface-muted);border:1px solid var(--border);border-radius:9px;padding:9px;margin:8px 0}.formula-card code{display:block;white-space:pre-wrap;overflow-wrap:anywhere}.formula-unavailable{display:block;color:var(--warning);font-size:12px}.chart [data-tooltip]{cursor:help}.chart [data-tooltip]:hover{filter:brightness(.85)}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}[data-panel][hidden]{display:none!important}@media(max-width:760px){.dashboard-topbar{display:block}.dashboard-statuses{justify-content:flex-start;margin-top:8px}.dashboard-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}
"""
